import sys, json, copy, hashlib
from pathlib import Path
from collections import Counter
from datetime import datetime, UTC
root=Path(sys.argv[1]); sys.path[:0]=[str(root/'src'),str(root/'tests')]
from pydantic import ValidationError
from m23c_fixtures import build,case_by_id,dataset
from editalfinder_v2.domain.integration import integrate
from editalfinder_v2.domain.integration_models import IntegrationReport,IntegrationInput
from editalfinder_v2.domain.models import RawSnapshot,ReviewAttestation,ValidationReport
counts=Counter(); details=[]
def reject(model,data,route,label):
    try:
        if route=='json': model.model_validate_json(json.dumps(data))
        elif route=='direct': model(**data)
        else: model.model_validate(data)
    except ValidationError as e:
        counts[label]+=1
        return e
    raise AssertionError((label,route,'accepted'))
def walk(v,path=()):
    if isinstance(v,dict):
        yield path,v
        for k,x in v.items(): yield from walk(x,path+(k,))
    elif isinstance(v,(list,tuple)):
        for k,x in enumerate(v): yield from walk(x,path+(k,))
def at(v,path):
    for k in path:v=v[k]
    return v
if len(sys.argv)>2 and sys.argv[2]=='corpus':
    rows=[]
    for case in dataset()['cases']:
        inp=build(case); out=integrate(inp)
        rows.append({'id':case['case_id'],'input':inp.model_dump_json(),'output':out.model_dump_json()})
    from m23_fixtures import build_case, FIXTURE
    for name in json.loads(FIXTURE.read_text()):
        inp=build_case(name); out=integrate(inp)
        rows.append({'id':name,'input':inp.model_dump_json(),'output':out.model_dump_json()})
    blob=json.dumps(rows,ensure_ascii=False,separators=(',',':')).encode()
    Path(sys.argv[3]).write_bytes(blob)
    print(json.dumps({'cases':len(rows),'bytes':len(blob),'sha256':hashlib.sha256(blob).hexdigest()}));sys.exit()
for case in ('M23C-A-001','M23C-I-005'):
    inp=build(case_by_id(case)); report=integrate(inp)
    assert isinstance(report,IntegrationReport)
    assert integrate(inp).model_dump_json()==report.model_dump_json()
    assert not report.promotable
    for route in ('direct','python','json'):
        data=report.model_dump(mode='json' if route=='json' else 'python')
        for path,obj in walk(data):
            if 'algorithm' in obj and ('report_digest' in obj or 'payload_digest' in obj):
                for field in obj:
                    raw=copy.deepcopy(data); del at(raw,path)[field]
                    e=reject(IntegrationReport,raw,route,'nested_audit_omissions')
                    assert any(x['type']=='missing' and x['loc'][-1]==field for x in e.errors())
                    details.append([case,route,list(path),field])
            if isinstance(obj.get('audit'),dict):
                for field in obj:
                    if field.endswith('_version'):
                        raw=copy.deepcopy(data);del at(raw,path)[field]
                        reject(IntegrationReport,raw,route,'body_version_omissions')
    archived=json.loads(report.model_dump_json())
    del archived['candidates'][0]['normalizations']['financial']['audit']['limits_version']
    before=json.dumps(archived)
    reject(IntegrationReport,archived,'json','archive_rejection')
    out=integrate(IntegrationInput.model_validate_json(json.dumps(archived['input'])))
    assert out==report and json.dumps(archived)==before and not out.promotable
    counts['reprocessing']+=1
    for omitted in (False,True):
        raw=report.model_dump();raw['audit']=None
        if omitted:del raw['audit']
        assert IntegrationReport.model_validate(raw)==report
        counts['local_evaluation']+=1
snapshot=dict(id='00000000-0000-0000-0000-000000000001',source_id='00000000-0000-0000-0000-000000000003',source_code='fapergs',execution_id='00000000-0000-0000-0000-000000000002',collector_version='audit-local',url='https://example.org/',payload_json='{}')
review=dict(id=snapshot['id'],reviewer_identity='untrusted',candidate_id=snapshot['id'],candidate_digest='0'*64,evidence_digests=['0'*64],policy_version='test',decision='REVIEW',provenance='synthetic')
for model,base,field in ((RawSnapshot,snapshot,'collected_at'),(ReviewAttestation,review,'reviewed_at')):
    for route in ('direct','python','json'):
        for stamp in ('0001-01-01T00:00:00+23:59','9999-12-31T23:59:59-23:59'):
            e=reject(model,dict(base,**{field:stamp}),route,'utc_overflows')
            assert e.errors()[0]['loc']==(field,)
            if route!='json':reject(model,dict(base,**{field:datetime.fromisoformat(stamp)}),route,'datetime_overflows')
            body=integrate(build(case_by_id('M23C-A-001'))).candidates[0].validation.model_dump(mode='json' if route=='json' else 'python')
            if model is ReviewAttestation:body['review_attestations']=[dict(base,reviewed_at=stamp)]
            else:body['snapshots'][0]['collected_at']=stamp
            reject(ValidationReport,body,route,'nested_utc_overflows')
        reject(model,dict(base,**{field:'2026-03-12T10:15:30'}),route,'naive_rejection')
    for stamp in ('0001-01-02T00:00:00+23:59','9999-12-30T23:59:59-23:59','0001-01-01T23:59:00+23:59','9999-12-31T00:00:59.999999-23:59'):
        obj=model.model_validate(dict(base,**{field:stamp}))
        assert getattr(obj,field)==datetime.fromisoformat(stamp).astimezone(UTC)
        counts['exact_adjacent_conversion']+=1
result={'counts':dict(counts),'omission_inventory':details,'status':'PASS'}
Path('/home/lorenzozm/.hermes/cache/scratch/m23d1_independent_probe_results.json').write_text(json.dumps(result,indent=2))
print(json.dumps({'counts':dict(counts),'status':'PASS'}))
